function run_inclined_modes(maxFrames,tag,search,replay)
if nargin<1,maxFrames=Inf;end;if nargin<2,tag='inclined_wall_modes_20261010';end
if nargin<4,replay=struct;end
[root,~]=setup_tsfs;source=fullfile(root,'results','runs','inclined_wall_bidirectional_20261008','inclined_wall','truth.mat');if isfield(replay,'source'),source=replay.source;end;a=load(source);frames=tsfs.read_input(a.input);t=a.truth;o=tsfs.defaults;o.gapTolerance=1e-6;o.momentTolerance=200e-6;cfg=struct('constraintTolerance',1e-6,'sensorStd',1e-4,'forcePriors',false,'solver','enumerative-MINLP/fmincon-SQP','exactCircularFriction',true,'modeInitialization','previous chosen assignment first','continuousInitialization','existing previous-state seed; sliding direction from current geometric shape and previous estimated shape','allAssignments',true,'globalContinuousCertificate',false,'maxIterationsPerAssignment',300,'maxEvaluationsPerAssignment',5000,'optimalityTolerance',1e-8,'stepTolerance',1e-12,'objectiveScale',1e-4);
if nargin>=3,fields=fieldnames(search);for j=1:numel(fields),cfg.(fields{j})=search.(fields{j});end,end
folder=fullfile(root,'results','runs',tag);pub=fullfile(root,'results','published',tag);if ~isfolder(folder),mkdir(folder);end;if ~isfolder(pub),mkdir(pub);end;atomic_write_artifact(fullfile(pub,'configuration.json'),'json',cfg);rows=[];branches=[];mus=[.3 0];if isfield(cfg,'estimatorMus'),mus=cfg.estimatorMus;end;runs=cell(numel(mus),min(maxFrames,numel(frames)));
for j=1:numel(mus)
 previous=[];if isfield(replay,'initialEstimates'),previous=replay.initialEstimates{j};end
 for k=1:min(maxFrames,numel(frames))
  fr=frames{k};fr.mu(:)=mus(j);fr.previous.mu(:)=mus(j);fr.CU=eye(numel(fr.u))*cfg.sensorStd^2;fr.previous.CU=fr.CU;
  if isfield(cfg,'reportFrameStart')&&cfg.reportFrameStart,fprintf('BEGIN MODE mu %.1f frame %d/%d\n',mus(j),k,numel(frames));end
  clock=tic;restoredSeed=k==1&&isfield(replay,'initialEstimates');
  if restoredSeed
   g=previous.geometry;g.seconds=0;sol=previous.mechanics;d=previous.diagnostics;sol.reason='saved-insertion-state';sol.iterations=0;sol.selectedIterations=0;sol.selectedSeconds=0;sol.seconds=0;sol.trace=[];sol.counts=struct('augmentedIVPs',0,'rhsEvaluations',0,'odeSegments',0,'failedIVPs',0);sol.selectedCounts=sol.counts;sol.attempts={};sol.attemptSummary=[];sol.integerAssignmentsTested=0;sol.integerAssignmentsPossible=0;sol.selectedAttempt=0;sol.previousMode=sol.mode;sol.stoppedEarly=false;
  else
  g=tsfs.geometry(fr,o);if isfield(cfg,'solverFunction'),sol=feval(cfg.solverFunction,fr,g,previous,o,cfg);else,sol=tsfs.mode_solve(fr,g,previous,o,cfg);end;d=tsfs.diagnose(fr,g,sol,o);if sol.conditionalSearch&&~sol.modeAccepted,d.flags{end+1}='no-acceptable-contact-mode';end
  end
  sh=sol.evaluation.shape;
  out=struct('valid',true,'time',fr.time,'geometry',g,'mechanics',sol,'diagnostics',d,'contactForce',sh.force,'tipForce',sh.x(4:6),'seconds',toc(clock));if restoredSeed,out.seconds=0;end;previous=out;fc=sum(sh.force,2);err=sh.p-t.p(:,:,k);sc=NaN;arcerr=NaN;if numel(g.s)==1,sc=g.s;arcerr=sc-t.contactS(k);end
  ft=sh.x(4:6);n=t.planeNormal;tiperr=norm(ft-t.tipForce(:,k));contacterr=norm(fc-t.contactForce(:,k));shapeerr=sqrt(mean(sum(err.^2,1)));
  angle=NaN;if isfield(t,'angleDeg'),angle=t.angleDeg(k);end
  outerIterations=0;affineEvaluations=0;if ~restoredSeed&&isfield(sol,'outerIterations'),outerIterations=sol.outerIterations;affineEvaluations=sol.counts.affineEvaluations;end
  rows=[rows;struct('outerIterations',outerIterations,'affineEvaluations',affineEvaluations,'angleDeg',angle,'restoredSeed',restoredSeed,'normalErrorDeg',acosd(max(-1,min(1,n'*g.normal(:,1)))),'stage1TipErrorMm',norm(g.kinematicShape.p(:,end)-t.p(:,end,k)),'geometryExitflag',g.exitflag,'stage1ShapeRmsMm',sqrt(mean(sum((interp1(g.kinematicShape.s,g.kinematicShape.p',t.sMm,'pchip')'-t.p(:,:,k)).^2,1))),'method',j,'mu',mus(j),'frame',k,'distanceMm',t.distanceMm(k),'seconds',out.seconds,'geometrySeconds',g.seconds,'mechanicsSeconds',sol.seconds,'iterations',sol.iterations,'ivps',sol.counts.augmentedIVPs,'rhsEvaluations',sol.counts.rhsEvaluations,'failedIVPs',sol.counts.failedIVPs,'selectedIterations',sol.selectedIterations,'selectedIvps',sol.selectedCounts.augmentedIVPs,'selectedSeconds',sol.selectedSeconds,'assignments',sol.integerAssignmentsTested,'selectedAttempt',sol.selectedAttempt,'possibleAssignments',sol.integerAssignmentsPossible,'modeAccepted',sol.modeAccepted,'fbgRmsAcceptance',sol.fbgRmsAcceptance,'stoppedEarly',sol.stoppedEarly,'mode',mat2str(sol.mode),'previousMode',mat2str(sol.previousMode),'converged',sol.converged,'modeFeasible',sol.modeFeasible,'solverSuccess',sol.converged&&sol.modeFeasible,'reason',sol.reason,'stationarity',sol.stationarity,'objective',sol.evaluation.objective,'objectiveTerms',numel(sol.evaluation.r),'candidateCount',numel(g.s),'activeCount',d.activeCount,'estimatedArcMm',sc,'arcErrorMm',arcerr,'tipErrorN',tiperr,'contactErrorN',contacterr,'shapeRmsMm',shapeerr,'shapeTipErrorMm',norm(err(:,end)),'tipFx',ft(1),'tipFy',ft(2),'tipFz',ft(3),'contactFx',fc(1),'contactFy',fc(2),'contactFz',fc(3),'normalN',n'*fc,'tangentN',[1;0;1]'/sqrt(2)*fc,'fbgRms',d.fbgRms,'curvatureRmsPerMm',sqrt(mean((sh.prediction(:)-fr.u(:)).^2)),'modeViolation',sol.modeViolation,'gapMm',max([0;abs(d.gapMm(:))]),'projectionN',max([0;abs(d.projectionN(:))]),'coneExcessN',max([0;d.coneExcessN(:)]),'workNmm',sum(d.frictionWorkNmm),'tangency',max([0;abs(d.tangency(:))]),'penetrationMm',d.maximumPenetrationMm,'truthPlanePenetrationMm',max(0,-min(n'*(sh.collisionP-t.planePoint))),'tipMomentNmm',norm(sh.tipMoment,inf),'flags',strjoin(d.flags,';'))];
  for ia=1:numel(sol.attemptSummary),rr=sol.attemptSummary(ia);rr.method=j;rr.mu=mus(j);rr.frame=k;rr.selected=ia==sol.selectedAttempt;branches=[branches;rr];end
  out.mechanics.evaluation.shape.pieces={};for ia=1:numel(out.mechanics.attempts),out.mechanics.attempts{ia}.evaluation.shape.pieces={};if isfield(out.mechanics.attempts{ia},'affineEvaluation'),out.mechanics.attempts{ia}.affineEvaluation.shape.pieces={};end;end;if isfield(out.mechanics,'affineEvaluation'),out.mechanics.affineEvaluation.shape.pieces={};end;out.geometry.kinematicShape.Jp=[];out.geometry.kinematicShape.Jt=[];runs{j,k}=out;
  writetable(struct2table(rows,'AsArray',true),fullfile(pub,'estimates.csv'));if ~isempty(branches),writetable(struct2table(branches,'AsArray',true),fullfile(pub,'branch_attempts.csv'));end;checkpointEvery=1;if isfield(cfg,'checkpointEvery'),checkpointEvery=cfg.checkpointEvery;end;if k==1||mod(k,checkpointEvery)==0||k==size(runs,2),checkpoint=fullfile(folder,'comparison_pending.mat');save(checkpoint,'runs','rows','branches','cfg','o','mus','-v7.3');movefile(checkpoint,fullfile(folder,'comparison.mat'),'f');end;
  fprintf('MODE mu %.1f frame %d/%d d %.0f mode%s previous%s: %.2fs %d total-it %d total-IVP (%d selected-it) success%d tip %.5g contact %.5g shape %.5g %s\n',mus(j),k,numel(frames),t.distanceMm(k),mat2str(sol.mode),mat2str(sol.previousMode),out.seconds,sol.iterations,sol.counts.augmentedIVPs,sol.selectedIterations,rows(end).solverSuccess,tiperr,contacterr,shapeerr,sol.reason);
 end
end
end
